@theme {
  --color-ink: #111618;
  --color-paper: #F4EFE6;
  --color-accent: #1E51EB;
  --color-steel: #7E8A90;
  --color-pine: #DED7C5;

  --font-display: var(--font-chivo), -apple-system, system-ui, sans-serif;
  --font-body: var(--font-jakarta), -apple-system, system-ui, sans-serif;
  --font-mono: var(--font-chivo-mono), ui-monospace, monospace;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-spring: linear(0, 0.35 8%, 0.82 20%, 1.06 30%, 1.02 42%, 0.99 58%, 1);

  --dur-instant: 90ms;
  --dur-fast: 180ms;
  --dur-base: 420ms;
  --dur-slow: 800ms;
  --dur-hero: 1200ms;

  --reveal-shift: 28px;
  --stagger: 70ms;
}

/* ── Base layout ────────────────────────────────────────── */
html {
  scroll-behavior: smooth;
  overflow-x: clip;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

.lh-body {
  margin: 0;
  background-color: #F4EFE6;
  color: #111618;
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
  background-image: radial-gradient(#7E8A90 1.5px, transparent 1.5px);
  background-size: 24px 24px;
}

.lh-display {
  font-family: var(--font-display);
}

.lh-mono {
  font-family: var(--font-mono);
}

.lh-wrap {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 clamp(16px, 4vw, 48px);
}

.lh-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.lh-text-accent {
  color: #1E51EB;
}

/* Focus visibility */
:focus-visible {
  outline: 2px solid #1E51EB;
  outline-offset: 3px;
}

/* ── Buttons ────────────────────────────────────────────── */
.lh-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.02em;
  padding: 13px 24px;
  border-radius: 4px;
  cursor: pointer;
  text-decoration: none;
  transition: transform var(--dur-instant) var(--ease-spring),
    background-color var(--dur-fast) var(--ease-out),
    color var(--dur-fast) var(--ease-out),
    border-color var(--dur-fast) var(--ease-out);
  border: 2px solid transparent;
}

.lh-btn:active {
  transform: scale(0.97);
}

.lh-btn-primary {
  background-color: #1E51EB;
  color: #F4EFE6;
  border-color: #1E51EB;
}

@media (hover: hover) and (pointer: fine) {
  .lh-btn-primary:hover {
    background-color: #111618;
    border-color: #111618;
    color: #F4EFE6;
  }
}

.lh-btn-secondary {
  background-color: #F4EFE6;
  color: #111618;
  border-color: #111618;
}

@media (hover: hover) and (pointer: fine) {
  .lh-btn-secondary:hover {
    background-color: #111618;
    color: #F4EFE6;
  }
}

.lh-btn-dark {
  background-color: #111618;
  color: #F4EFE6;
  border-color: #111618;
}

@media (hover: hover) and (pointer: fine) {
  .lh-btn-dark:hover {
    background-color: #1E51EB;
    border-color: #1E51EB;
  }
}

/* ── Top Bar ────────────────────────────────────────────── */
.lh-topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background-color: color-mix(in srgb, #F4EFE6 94%, transparent);
  border-bottom: 1px solid #7E8A90;
  backdrop-filter: blur(8px);
  transition: background-color var(--dur-fast) var(--ease-out),
    box-shadow var(--dur-fast) var(--ease-out);
}

.lh-topbar.is-scrolled {
  background-color: color-mix(in srgb, #F4EFE6 98%, transparent);
  box-shadow: 0 4px 16px color-mix(in srgb, #111618 8%, transparent);
}

.lh-topbar-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 12px clamp(16px, 4vw, 48px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.lh-brand-link {
  text-decoration: none;
  color: inherit;
  display: inline-flex;
}

.lh-telemetry-chip {
  display: none;
  align-items: center;
  gap: 8px;
  background-color: color-mix(in srgb, #7E8A90 20%, transparent);
  padding: 6px 14px;
  border-radius: 4px;
  border: 1px solid #7E8A90;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: #111618;
}

@media (min-width: 1024px) {
  .lh-telemetry-chip {
    display: flex;
  }
}

.lh-live-dot {
  width: 7px;
  height: 7px;
  border-radius: 9999px;
  background-color: #1E51EB;
  animation: lh-pulse 2s infinite ease-in-out;
}

@keyframes lh-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.8); }
}

.lh-nav {
  display: none;
  align-items: center;
  gap: 20px;
}

@media (min-width: 860px) {
  .lh-nav {
    display: flex;
  }
}

.lh-nav-link {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  text-decoration: none;
  color: #111618;
  letter-spacing: 0.04em;
  padding: 6px 8px;
  transition: color var(--dur-fast) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .lh-nav-link:hover {
    color: #1E51EB;
  }
}

.lh-nav-cta {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 700;
  background-color: #111618;
  color: #F4EFE6;
  text-decoration: none;
  padding: 8px 16px;
  border-radius: 4px;
  transition: background-color var(--dur-fast) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .lh-nav-cta:hover {
    background-color: #1E51EB;
  }
}

.lh-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: transparent;
  border: 1px solid #7E8A90;
  border-radius: 4px;
  font-size: 18px;
  cursor: pointer;
  color: #111618;
}

@media (min-width: 860px) {
  .lh-menu-btn {
    display: none;
  }
}

.lh-mobile-menu {
  display: flex;
  flex-direction: column;
  padding: 16px 24px;
  gap: 12px;
  background-color: #F4EFE6;
  border-top: 1px solid #7E8A90;
}

.lh-mobile-link {
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 600;
  color: #111618;
  text-decoration: none;
  padding: 8px 0;
}

.lh-mobile-cta {
  display: inline-block;
  text-align: center;
  font-family: var(--font-body);
  font-weight: 700;
  background-color: #1E51EB;
  color: #F4EFE6;
  text-decoration: none;
  padding: 12px;
  border-radius: 4px;
  margin-top: 8px;
}

/* ── Hero Section ───────────────────────────────────────── */
.lh-hero-section {
  padding-top: clamp(100px, 14vw, 150px);
  padding-bottom: clamp(40px, 6vw, 70px);
  border-bottom: 2px solid #7E8A90;
}

.lh-hero-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  align-items: center;
}

@media (min-width: 990px) {
  .lh-hero-grid {
    grid-template-columns: 1.15fr 0.85fr;
  }
}

.lh-hero-kicker-wrap {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.lh-hero-kicker {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: #1E51EB;
  background-color: color-mix(in srgb, #1E51EB 12%, transparent);
  padding: 4px 10px;
  border-radius: 3px;
  border: 1px solid color-mix(in srgb, #1E51EB 35%, transparent);
}

.lh-hero-code {
  font-family: var(--font-mono);
  font-size: 11px;
  color: #7E8A90;
  letter-spacing: 0.08em;
}

.lh-hero-headline {
  font-family: var(--font-display);
  font-size: clamp(40px, 7vw, 76px);
  font-weight: 900;
  line-height: 0.98;
  letter-spacing: -0.035em;
  margin: 0 0 20px;
  text-transform: uppercase;
}

.lh-mask-line {
  display: block;
  overflow: clip;
}

@media (prefers-reduced-motion: no-preference) {
  .lh-mask-line > span {
    display: block;
    animation: lh-mask-rise 900ms cubic-bezier(0.16, 1, 0.3, 1) both;
  }
  .lh-mask-line:nth-child(2) > span {
    animation-delay: 80ms;
  }
  .lh-mask-line:nth-child(3) > span {
    animation-delay: 160ms;
  }
}

@keyframes lh-mask-rise {
  from {
    transform: translateY(110%);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

.lh-hero-lead {
  font-size: clamp(16px, 2.2vw, 19px);
  color: color-mix(in srgb, #111618 85%, transparent);
  max-width: 54ch;
  margin: 0 0 32px;
  line-height: 1.55;
}

.lh-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

/* Hero Technical Blueprint Frame */
.lh-hero-technical {
  display: flex;
  justify-content: center;
}

.lh-hero-frame {
  width: 100%;
  max-width: 480px;
  background-color: #111618;
  color: #F4EFE6;
  border: 2px solid #7E8A90;
  border-radius: 6px;
  overflow: hidden;
  box-shadow: 8px 8px 0 #111618;
}

.lh-hero-frame-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
  background-color: color-mix(in srgb, #7E8A90 20%, transparent);
  border-bottom: 1px solid #7E8A90;
  font-family: var(--font-mono);
  font-size: 11px;
}

.lh-frame-serial {
  letter-spacing: 0.08em;
  color: #DED7C5;
}

.lh-frame-indicator {
  color: #1E51EB;
  font-weight: 700;
}

.lh-hero-blueprint {
  padding: 16px;
  background-color: #111618;
  background-image: linear-gradient(color-mix(in srgb, #7E8A90 14%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, #7E8A90 14%, transparent) 1px, transparent 1px);
  background-size: 16px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lh-blueprint-svg {
  width: 100%;
  height: auto;
}

.lh-hero-frame-footer {
  display: flex;
  justify-content: space-between;
  padding: 12px 16px;
  background-color: color-mix(in srgb, #111618 90%, #7E8A90);
  border-top: 1px solid #7E8A90;
}

.lh-spec-kicker {
  display: block;
  font-family: var(--font-mono);
  font-size: 10px;
  color: #7E8A90;
  letter-spacing: 0.06em;
}

.lh-spec-bold {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
}

/* Hero Telemetry Strip */
.lh-hero-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr));
  gap: 1px;
  background-color: #7E8A90;
  border: 1px solid #7E8A90;
  border-radius: 4px;
  margin-top: 48px;
  overflow: hidden;
}

.lh-strip-cell {
  background-color: #F4EFE6;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
}

.lh-strip-label {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: #7E8A90;
  letter-spacing: 0.08em;
  margin-bottom: 6px;
}

.lh-strip-val {
  font-family: var(--font-display);
  font-size: clamp(28px, 4vw, 36px);
  font-weight: 900;
  line-height: 1;
  color: #111618;
  margin-bottom: 4px;
}

.lh-strip-sub {
  font-size: 13px;
  color: color-mix(in srgb, #111618 70%, transparent);
}

/* ── Section Structure ──────────────────────────────────── */
.lh-section {
  padding: clamp(56px, 8vw, 100px) 0;
  border-bottom: 2px solid #7E8A90;
}

.lh-section-head {
  margin-bottom: 36px;
  max-width: 760px;
}

.lh-kicker {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: #1E51EB;
  margin-bottom: 8px;
}

.lh-section-title {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.025em;
  text-transform: uppercase;
  margin: 0 0 12px;
}

.lh-section-desc {
  font-size: clamp(16px, 2vw, 18px);
  color: color-mix(in srgb, #111618 80%, transparent);
  margin: 0;
}

/* ── Pegboard Station (The Signature Mechanic) ──────────── */
.lh-pegboard-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}

.lh-pegboard-tab {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  padding: 10px 18px;
  background-color: #F4EFE6;
  border: 1px solid #7E8A90;
  border-radius: 4px;
  cursor: pointer;
  color: #111618;
  transition: background-color var(--dur-fast) var(--ease-out),
    color var(--dur-fast) var(--ease-out),
    border-color var(--dur-fast) var(--ease-out);
}

.lh-pegboard-tab.is-active {
  background-color: #111618;
  border-color: #111618;
  color: #F4EFE6;
}

@media (hover: hover) and (pointer: fine) {
  .lh-pegboard-tab:hover:not(.is-active) {
    border-color: #1E51EB;
    color: #1E51EB;
  }
}

/* Caliper Inspection Panel */
.lh-caliper-panel {
  background-color: #111618;
  color: #F4EFE6;
  border: 2px solid #1E51EB;
  border-radius: 6px;
  margin-bottom: 32px;
  overflow: hidden;
  box-shadow: 0 8px 24px color-mix(in srgb, #111618 20%, transparent);
}

.lh-caliper-ruler {
  display: flex;
  justify-content: space-between;
  padding: 6px 20px;
  background-color: color-mix(in srgb, #7E8A90 25%, transparent);
  border-bottom: 1px dashed #7E8A90;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  color: #DED7C5;
}

.lh-caliper-body {
  padding: clamp(20px, 3vw, 32px);
}

.lh-caliper-meta {
  margin-bottom: 24px;
}

.lh-caliper-serial {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: #1E51EB;
  letter-spacing: 0.12em;
}

.lh-caliper-name {
  font-family: var(--font-display);
  font-size: clamp(24px, 4vw, 36px);
  font-weight: 900;
  letter-spacing: -0.02em;
  margin: 4px 0 2px;
}

.lh-caliper-model {
  font-family: var(--font-mono);
  font-size: 14px;
  color: #DED7C5;
  margin: 0;
}

.lh-caliper-specs-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr));
  gap: 16px;
  padding: 16px 0;
  border-top: 1px solid color-mix(in srgb, #7E8A90 40%, transparent);
  border-bottom: 1px solid color-mix(in srgb, #7E8A90 40%, transparent);
  margin-bottom: 24px;
}

.lh-spec-cell {
  display: flex;
  flex-direction: column;
}

.lh-spec-label {
  font-family: var(--font-mono);
  font-size: 10px;
  color: #7E8A90;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.lh-spec-val {
  font-size: 14px;
  font-weight: 600;
  color: #F4EFE6;
}

.lh-caliper-stage-btn {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 14px;
  padding: 12px 24px;
  border-radius: 4px;
  border: none;
  cursor: pointer;
  background-color: #1E51EB;
  color: #F4EFE6;
  transition: background-color var(--dur-fast) var(--ease-out), transform var(--dur-instant) var(--ease-spring);
}

.lh-caliper-stage-btn.is-staged {
  background-color: #DED7C5;
  color: #111618;
}

@media (hover: hover) and (pointer: fine) {
  .lh-caliper-stage-btn:hover {
    filter: brightness(1.1);
  }
}

/* Pegboard Layout */
.lh-pegboard-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 28px;
  align-items: start;
}

@media (min-width: 1024px) {
  .lh-pegboard-layout {
    grid-template-columns: 1.6fr 1fr;
  }
}

.lh-pegboard-canvas {
  background-color: #F4EFE6;
  border: 2px solid #111618;
  border-radius: 6px;
  padding: 24px;
  background-image: radial-gradient(#7E8A90 2px, transparent 2px);
  background-size: 20px 20px;
  box-shadow: 6px 6px 0 #111618;
}

.lh-pegboard-header-tag {
  display: flex;
  justify-content: space-between;
  padding-bottom: 16px;
  margin-bottom: 20px;
  border-bottom: 2px solid #111618;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #111618;
}

.lh-docks-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr));
  gap: 20px;
}

/* Individual Tool Dock */
.lh-tool-dock {
  position: relative;
  min-height: 280px;
  border-radius: 4px;
  cursor: pointer;
  outline: none;
}

.lh-dock-shadow {
  position: absolute;
  inset: 0;
  background-color: color-mix(in srgb, #DED7C5 70%, transparent);
  border: 2px dashed #7E8A90;
  border-radius: 4px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  z-index: 1;
}

.lh-dock-serial {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  color: #7E8A90;
  letter-spacing: 0.1em;
}

.lh-dock-silhouette-shape {
  width: 80px;
  height: 80px;
  opacity: 0.35;
}

.lh-dock-mount-status {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  color: #7E8A90;
}

/* Chassis that lifts on unlatch */
.lh-dock-chassis {
  position: relative;
  z-index: 2;
  background-color: #F4EFE6;
  border: 2px solid #111618;
  border-radius: 4px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  transition: transform var(--dur-base) var(--ease-spring),
    box-shadow var(--dur-base) var(--ease-out),
    border-color var(--dur-fast) var(--ease-out);
}

.lh-tool-dock.is-unlatched .lh-dock-chassis {
  transform: translateY(-8px) scale(1.02);
  border-color: #1E51EB;
  box-shadow: 0 12px 28px color-mix(in srgb, #111618 18%, transparent);
}

@media (hover: hover) and (pointer: fine) {
  .lh-tool-dock:hover:not(.is-unlatched) .lh-dock-chassis {
    transform: translateY(-4px);
    border-color: #1E51EB;
  }
}

.lh-dock-chassis-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.lh-dock-badge {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #1E51EB;
}

.lh-dock-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 9999px;
  background-color: #7E8A90;
}

.lh-dock-status-dot.is-staged-dot {
  background-color: #1E51EB;
}

.lh-dock-illustration {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px 0;
}

.lh-schematic-svg {
  width: 90px;
  height: 90px;
}

.lh-dock-title {
  font-family: var(--font-display);
  font-size: 16px;
