  font-weight: bold;
}

.lh-requisition-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.lh-form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.lh-form-label {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  color: #DED7C5;
  letter-spacing: 0.04em;
}

.lh-form-label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.lh-form-range-val {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
  background-color: #1E51EB;
  color: #F4EFE6;
  padding: 2px 8px;
  border-radius: 3px;
}

.lh-required {
  color: #1E51EB;
}

.lh-form-input,
.lh-form-select,
.lh-form-textarea {
  font-family: var(--font-body);
  font-size: 15px;
  padding: 12px 14px;
  border-radius: 4px;
  border: 1px solid #7E8A90;
  background-color: #111618;
  color: #F4EFE6;
  outline: none;
  transition: border-color var(--dur-fast) var(--ease-out), box-shadow var(--dur-fast) var(--ease-out);
}

.lh-form-input:focus,
.lh-form-select:focus,
.lh-form-textarea:focus {
  border-color: #1E51EB;
  box-shadow: 0 0 0 2px color-mix(in srgb, #1E51EB 30%, transparent);
}

.lh-form-input.is-invalid,
.lh-form-select.is-invalid {
  border-color: #1E51EB;
  animation: lh-shake 280ms ease-in-out;
}

@keyframes lh-shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-6px); }
  75% { transform: translateX(6px); }
}

.lh-form-range {
  width: 100%;
  accent-color: #1E51EB;
  cursor: pointer;
}

.lh-range-markers {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 10px;
  color: #7E8A90;
  margin-top: 4px;
}

