  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: 4px;
}

.lh-checkbox {
  width: 18px;
  height: 18px;
  accent-color: #1E51EB;
  cursor: pointer;
  margin-top: 3px;
}

.lh-checkbox-label {
  font-size: 13px;
  color: #DED7C5;
  line-height: 1.45;
  cursor: pointer;
}

.lh-form-error {
  font-family: var(--font-mono);
  font-size: 11px;
  color: #1E51EB;
  margin: 4px 0 0;
  letter-spacing: 0.02em;
}

.lh-form-success {
  background-color: #111618;
  border: 2px solid #1E51EB;
  border-radius: 6px;
  padding: 28px;
  animation: lh-scale-in var(--dur-base) var(--ease-out);
}

@keyframes lh-scale-in {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.lh-success-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  background-color: #1E51EB;
  color: #F4EFE6;
  padding: 4px 10px;
  border-radius: 3px;
  margin-bottom: 12px;
}

.lh-success-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 900;
  margin: 0 0 6px;
}

.lh-success-code {
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 700;
  color: #DED7C5;
  margin: 0 0 20px;
  padding-bottom: 14px;
  border-bottom: 1px dashed #7E8A90;
}

.lh-success-details {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

.lh-success-row {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
}

.lh-success-row span {
  color: #7E8A90;
}

.lh-success-row strong {
  color: #F4EFE6;
}

.lh-success-note {
  font-size: 12px;
  color: #DED7C5;
  margin: 0 0 24px;
  line-height: 1.5;
}

/* ── Footer ─────────────────────────────────────────────── */
.lh-footer {
  background-color: #111618;
  color: #F4EFE6;
  border-top: 2px solid #7E8A90;
  padding: clamp(48px, 6vw, 80px) 0 36px;
}

.lh-footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr));
  gap: 36px;
  margin-bottom: 48px;
}

.lh-footer-brand {
  grid-column: 1 / -1;
}

@media (min-width: 900px) {
  .lh-footer-brand {
    grid-column: span 2;
  }
}

.lh-footer-motto {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 900;
  color: #1E51EB;
  margin: 16px 0 8px;
  letter-spacing: -0.01em;
}

.lh-footer-desc {
  font-size: 13px;
  color: #7E8A90;
  max-width: 44ch;
  line-height: 1.5;
  margin: 0;
}

.lh-footer-col-title {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #DED7C5;
  margin: 0 0 16px;
}

.lh-footer-links {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.lh-footer-link {
  font-size: 13px;
  color: #7E8A90;
  text-decoration: none;
  transition: color var(--dur-fast) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .lh-footer-link:hover {
    color: #F4EFE6;
  }
}

.lh-footer-static-item {
  font-size: 13px;
  color: #7E8A90;
}

.lh-footer-bottom {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  border-top: 1px solid color-mix(in srgb, #7E8A90 30%, transparent);
  padding-top: 24px;
}

.lh-footer-copy {
  font-family: var(--font-mono);
  font-size: 11px;
  color: #7E8A90;
}

.lh-footer-back-to-top {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: #F4EFE6;
  text-decoration: none;
}

/* ── Motion System Reveals ──────────────────────────────── */
@media (prefers-reduced-motion: no-preference) {
  [data-reveal] {
    transition: opacity var(--dur-slow) var(--ease-out),
      transform var(--dur-slow) var(--ease-out),
      clip-path var(--dur-slow) var(--ease-in-out);
    transition-delay: calc(var(--delay, 0ms) + var(--i, 0) * var(--stagger));
  }

  [data-reveal="rise"]:not([data-in="true"]) {
    opacity: 0;
    transform: translateY(var(--reveal-shift));
  }

  [data-reveal="scale"]:not([data-in="true"]) {
    opacity: 0;
    transform: scale(0.96);
  }

  [data-reveal="wipe"]:not([data-in="true"]) {
    clip-path: inset(0 0 100% 0);
  }

  [data-reveal="draw"]:not([data-in="true"]) {
    transform: scaleX(0);
    transform-origin: left;
  }
}
